def family_init(ctx):
    ctx.r = ctx.indicator("rsi", period=int(ctx.p.rsi_n))


def _band(ctx, j):
    """(upper, lower) = 50 +/- mult * dispersion of the RSI over band_n bars."""
    n = int(ctx.p.band_n)
    if n < 2 or j < n - 1:
        return None, None
    vals = []
    for k in range(n):
        x = ctx.r[j - k]
        if x is None:
            return None, None
        vals.append(x)
    m = sum(vals) / n
    if int(ctx.p.est) == 0:
        dev = (sum((x - m) ** 2 for x in vals) / n) ** 0.5
    else:
        dev = sum(abs(x - m) for x in vals) / n
    adj = float(ctx.p.mult) * dev
    return 50.0 + adj, 50.0 - adj


def signal(ctx, i):
    if i < 1:
        return 0
    r = ctx.r[i]
    pr = ctx.r[i - 1]
    if r is None or pr is None:
        return 0
    ob, os_ = _band(ctx, i)
    pob, pos_ = _band(ctx, i - 1)
    if ob is None or pob is None:
        return 0
    if int(ctx.p.mode) == 0:
        if pr <= pob and r > ob:
            return 1
        if pr >= pos_ and r < os_:
            return -1
        return 0
    if pr <= pos_ and r > os_:
        return 1
    if pr >= pob and r < ob:
        return -1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    r = ctx.r[i]
    if r is None:
        return False
    ob, os_ = _band(ctx, i)
    if ob is None:
        return False
    if ctx.positions[0]["side"] == "long":
        return r < 50.0 or r < os_
    return r > 50.0 or r > ob
